'use strict';
const $ = id => document.getElementById(id);
const categories = [
 ['face','Личное присутствие','Речь, жесты, мимика, письмо, рисунок, тактильные сигналы'],
 ['phone','Телефонная сеть','Голосовые вызовы, SMS, MMS, USSD'],
 ['messenger','Мессенджеры','WhatsApp, Telegram, Signal, WeChat, LINE, Viber и аналоги'],
 ['video','Видеосвязь','Видеозвонки, конференции, совместное присутствие'],
 ['mail','Электронная почта','Письма, списки рассылки, вложения'],
 ['social','Социальные сети','Публикации, комментарии, личные сообщения, сообщества'],
 ['media','Медиа и файлы','Фото, видео, аудио, документы, ссылки, физические носители'],
 ['forum','Форумы и сообщества','Темы, обсуждения, вопросы и ответы'],
 ['broadcast','Публичное вещание','Радио, телевидение, стримы, публичные объявления'],
 ['collab','Совместная работа','Документы, доски, задачи, календари, игровые пространства'],
 ['access','Доступность и преобразование','Субтитры, STT/TTS, OCR, Брайль, AAC, экранный диктор, тактильный вывод'],
 ['value','Передача ценности','Наличные, переводы, карты, кошельки, QR, счета, чаевые, подарки, пожертвования, долг, заём, бартер'],
 ['machine','Человек—машина','Голосовые интерфейсы, устройства, датчики, ассистивные технологии']
];
const choices = {
 message:[['Текстовый черновик','Подходит для асинхронного сообщения; остаётся доступным для редактирования.','mail messenger social'],['Голосовое сообщение / звонок','Подходит, если обеим сторонам удобно воспринимать речь.','phone messenger'],['Письмо с вложением','Уместно для длинного текста и документов.','mail media'],['Личное или тактильное сообщение','Для ситуации рядом; формат согласуется с человеком.','face access']],
 talk:[['Голосовой звонок','Быстрый синхронный контакт, если доступен обоим.','phone messenger'],['Видеозвонок','Может передавать мимику и жесты; качество зависит от сети и навыков.','video messenger'],['Текстовый чат','Альтернатива речи; может быть удобен при шуме или ограничении слуха.','messenger mail'],['Личное общение','Включает речь, письмо, жесты и согласованные тактильные сигналы.','face access']],
 share:[['Передать файл или ссылку','Проверьте права доступа, размер и приватность вложения.','media messenger mail'],['Фото / видео с описанием','Добавьте текстовую альтернативу для людей, которым недоступно изображение.','media social access'],['Совместный документ','Полезен для совместного редактирования и истории изменений.','collab']],
 gather:[['Создать событие и пригласить круг','Использовать ·18 СОБЫТИЕ и ·23 КРУГ после проверки их реального API.','collab messenger mail'],['Групповой чат или звонок','Уточнить формат участия и доступность заранее.','messenger video'],['Публичное объявление','Для широкого круга; не раскрывать приватные данные.','broadcast social']],
 publish:[['Публикация в сообществе','Выберите аудиторию, срок и правила удаления.','social forum'],['Прямой эфир / вещание','Нужны субтитры, описание и альтернативный канал вопросов.','broadcast video'],['Письмо группе','Подходит для списка адресатов с явным согласием.','mail']],
 value:[['Сначала зафиксировать намерение','Уточнить сумму/предмет, получателя, условия и подтверждение; это ещё не платёж.','value'],['Перейти к выбранному пользователем платёжному инструменту','Только внешний переход после явного выбора; здесь реального перевода нет.','value'],['Подарок, долг или бартер','Описать договорённость отдельно от фактической передачи ценности.','value messenger']],
 access:[['Текст ↔ озвучивание','Использовать системный TTS/STT, если браузер/устройство поддерживает.','access machine'],['Субтитры и транскрипт','Сохранить смысл и обозначить ошибки распознавания.','access video'],['Брайль / тактильный вывод / AAC','Подключать только совместимый адаптер; не имитировать работу устройства.','access machine'],['Жестовый язык с человеком','В MVP без автоматического распознавания жестов; поддержать ручной/человеческий путь.','access face']],
 find:[['Поиск по локальным записям','Ищет только сохранённые здесь черновики и журнал прототипа.','machine'],['Открыть каталог способов','Выбрать класс канала, затем конкретный сервис или адаптер.','collab']]
};
let selectedChoice = null;
const Core = window.SingulyarCore;
const Adapters = window.SingulyarAdapters;
const classMap={face:'in-person',phone:'telephony',messenger:'messaging',video:'video-call',mail:'email',social:'social-network',media:'media-file',forum:'forum',broadcast:'broadcast',collab:'collaboration',access:'accessibility',value:'value-transfer',machine:'human-machine'};
const modalityLabels={text:'текст',speech:'речь/диктовка',audio:'аудио',video:'видео',image:'изображение', 'sign-manual':'жесты вручную',braille:'Брайль',tactile:'тактильный вывод',aac:'AAC',file:'файл','value-transfer':'передача ценности'};
function readForm(){return {intent:$('intent').value,recipient:$('recipient').value.trim()||null,urgency:$('urgency').value,text:$('message').value,fromModality:$('from').value,toModality:$('to').value,choiceId:selectedChoice?selectedChoice.id:null,choiceLabel:selectedChoice?selectedChoice.label:null,classes:selectedChoice?selectedChoice.classes:[],capabilityId:selectedChoice?selectedChoice.capabilityId:'local-draft',capabilityStatus:selectedChoice?selectedChoice.capabilityStatus:'available',consentToSend:false};}
function makeEvent(){return Core.createIntent(readForm());}
function trace(lines){$('trace').innerHTML='';lines.forEach(x=>{const li=document.createElement('li');li.textContent=x;$('trace').append(li)});}
function renderCapabilities(){const list=Adapters.list();$('capabilities').textContent='Реестр возможностей: '+list.map(a=>`${a.label} — ${a.status==='available'?'доступен локально':a.status==='capability-check-required'?'нужна проверка устройства':'не подключён'}`).join(' · ');}
function recommend(){
 const input=readForm(), intent=input.intent, from=input.fromModality, to=input.toModality, urgency=input.urgency;
 const items=(choices[intent]||choices.message).map((it,i)=>({id:`${intent}-${i}`,label:it[0],description:it[1],rawClasses:it[2].split(' '),classes:it[2].split(' ').map(k=>classMap[k]||k)}));
 const ranked=Core.rankChoices({intent:input.intent,content:{fromModality:from,toModality:to},urgency},items,{fromModality:from,toModality:to,urgency,privacy:'normal'}).map(it=>{let aid='local-draft';if(it.classes.includes('messaging'))aid='matrix';else if(it.classes.includes('social-network')||it.classes.includes('broadcast'))aid='activitypub';else if(it.classes.includes('value-transfer'))aid='payment-link';else if(it.classes.includes('accessibility')&&(to==='speech'||to==='audio'))aid='system-tts';const a=Adapters.get(aid);return {...it,capabilityId:aid,capabilityStatus:a?a.status:'unsupported',capabilityLabel:a?a.label:'Нет адаптера',capabilityDescription:a?a.description:'Реестр не содержит адаптера для исполнения этого варианта.'};});
 $('options').innerHTML='';ranked.forEach((it,i)=>{const el=document.createElement('article');el.className='option';el.innerHTML='<span class="tag"></span><h3></h3><p></p><p class="muted"></p><p class="muted score"></p><button class="secondary choose" type="button">Выбрать для черновика</button>';el.querySelector('.tag').textContent=`Вариант ${i+1}`;el.querySelector('h3').textContent=it.label;el.querySelectorAll('p')[0].textContent=it.description;el.querySelectorAll('p')[1].textContent='Классы: '+it.rawClasses.join(', ');el.querySelector('.score').textContent=`Оценка соответствия: ${it.score}. Исполнитель: ${it.capabilityLabel} (${it.capabilityStatus}). ${it.capabilityDescription} Внешняя доставка: не выполнялась.`;el.querySelector('button').addEventListener('click',()=>{selectedChoice=it;$('status').textContent='Выбран вариант: '+it.label+' · '+it.capabilityStatus+' · ещё не отправлено';trace([`Намерение: ${intent}`,`Предпочтительный ввод: ${modalityLabels[from]||from}`,`Предпочтительное восприятие: ${modalityLabels[to]||to}`,`Срочность: ${urgency}`,`Выбор человека: ${it.label}`,`Оценка соответствия: ${it.score}`,`Доставка: не выполнялась`]);});$('options').append(el);});
 trace([`Намерение: ${intent}`,`Ввод: ${modalityLabels[from]||from}`,`Восприятие адресата: ${modalityLabels[to]||to}`,`Срочность: ${urgency}`,`Показано вариантов: ${ranked.length}`,`Ранжирование: детерминированная эвристика; внешние сервисы не опрашивались`,`Автоматическая отправка: отключена`]);
}
$('recommend').addEventListener('click',recommend);
$('compose').addEventListener('click',()=>{try{const e=makeEvent();const errors=Core.validateIntent(e);if(errors.length)throw new Error(errors.join(', '));localStorage.setItem('singulyar.emergent.draft',JSON.stringify(e));$('status').textContent='Текущий черновик сохранён локально · не отправлен';trace(['Сохранено актуальное состояние формы в localStorage этого браузера.','Контракт события прошёл встроенную проверку.','Серверной отправки нет.']);}catch(e){$('status').textContent='Не удалось сохранить: '+e.message;}});
$('export').addEventListener('click',()=>{try{const e=makeEvent();const errors=Core.validateIntent(e);if(errors.length)throw new Error(errors.join(', '));const blob=new Blob([JSON.stringify(e,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='singulyar-intent-event.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);$('status').textContent='Текущее событие экспортировано в JSON · не отправлено';trace(['Экспортирован актуальный снимок формы, а не сохранённое ранее состояние.','Встроенная проверка контракта пройдена.','Получатель и содержание остаются под контролем человека.']);}catch(e){$('status').textContent='Экспорт не выполнен: '+e.message;}});
$('clear').addEventListener('click',()=>{try{localStorage.removeItem('singulyar.emergent.draft');}catch(e){} const restoreButton=$('restoreDraftButton');if(restoreButton)restoreButton.remove();$('intent').value='message';$('recipient').value='';$('urgency').value='normal';$('message').value='';$('from').value='text';$('to').value='text';selectedChoice=null;$('options').innerHTML='<article class="option"><h3>Черновик очищен</h3><p>Заполните намерение и подберите варианты.</p></article>';$('status').textContent='Локальный черновик удалён; форма сброшена';trace(['Форма сброшена к исходным значениям.','Локальная запись удалена, если хранилище доступно.','Внешняя доставка не выполнялась.']);});
const c=$('catalog');categories.forEach(([id,title,desc])=>{const el=document.createElement('div');el.className='catalog-item';const h=document.createElement('h3');h.textContent=title;const p=document.createElement('p');p.textContent=desc;el.append(h,p);c.append(el)});
try{const saved=localStorage.getItem('singulyar.emergent.draft');if(saved){const e=JSON.parse(saved);if(Core.validateIntent(e).length===0){$('status').textContent='Найден локальный черновик · нажмите «Восстановить» ниже';const restore=document.createElement('button');restore.type='button';restore.id='restoreDraftButton';restore.className='secondary';restore.textContent='Восстановить черновик';restore.addEventListener('click',()=>{try{const x=JSON.parse(localStorage.getItem('singulyar.emergent.draft'));if(Core.validateIntent(x).length)throw new Error('контракт не пройден');$('intent').value=x.intent;$('recipient').value=x.recipient||'';$('urgency').value=x.urgency;$('message').value=x.content.text;$('from').value=x.content.fromModality;$('to').value=x.content.toModality;selectedChoice=x.proposal.choiceId?{id:x.proposal.choiceId,label:x.proposal.label,classes:x.proposal.classes,rawClasses:x.proposal.classes,capabilityId:x.proposal.capabilityId,capabilityStatus:x.proposal.capabilityStatus}:null;$('status').textContent='Черновик восстановлен в форму · не отправлен';trace(['Восстановлена форма из локального черновика.','Проверьте адресата и содержание перед дальнейшим использованием.']);}catch(err){$('status').textContent='Восстановление не удалось: '+err.message;}});$('status').after(restore);}else{$('status').textContent='Найден повреждённый черновик; он не восстановлен';}}}catch(e){$('status').textContent='Локальное хранилище недоступно; можно продолжать без сохранения';}
$('catalogSearch').addEventListener('input',()=>{const q=$('catalogSearch').value.trim().toLocaleLowerCase('ru');let n=0;[...$('catalog').children].forEach(el=>{const match=!q||el.textContent.toLocaleLowerCase('ru').includes(q);el.hidden=!match;if(match)n++;});let draft='';try{const raw=localStorage.getItem('singulyar.emergent.draft');if(raw&&q&&raw.toLocaleLowerCase('ru').includes(q))draft=' Запрос также найден в сохранённом локальном черновике.';}catch(e){}$('searchResults').textContent=q?`Совпадений в каталоге: ${n}.${draft} Внешние аккаунты и сервисы не индексируются.`:'Введите запрос. Поиск не обращается к внешним платформам.';});
renderCapabilities();
